import { gsap } from 'gsap';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, resolution, uv, vec3, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;
  const group = new Group();

  // Plane geometry
  const geometry = new PlaneGeometry(5.12, 3.2); // aspect ratio from atlas region 512x320
  // Material with loaded texture
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Load texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Subtle grain via basic noise? Not required; image likely has grain.
  // Could add a very subtle procedural grain using TSL, but skipping for simplicity.

  // No primitives, no text, no interactions.

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // No GSAP timelines to kill
  };

  // Set position/rotation/scale as per spec (adapter may override, but include)
  group.position.set(-3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  return group;
}
